mapper.insert:
/* logs-mapper.xml id="insertErrorLog" 에러 로그 저장  */
INSERT
  INTO tbsy_error_log
  	 ( mb_id                 /* 회사코드 VARCHAR(20)*/
	 , emp_cd                /* 에러 발생자 사번 VARCHAR(40)*/
	 , action_type			 /* 행위 유형 VARCHAR(20) */
	 , error_url             /* 에러 발생 URL VARCHAR(20)*/
	 , error_query_string    /* 전달된 파라미터 값 VARCHAR(1000)*/
	 , error_status          /* 에러 상태 코드 VARCHAR(40)*/
	 , error_class           /* 에러 발생 클래스 VARCHAR(400)*/
	 , error_msg             /* 에러 메세지 VARCHAR(4000)*/
	 , error_trace           /* 에러 추적 메세지 VARCHAR(4000)*/
	 , error_ip              /* 에러 발생 IP VARCHAR(100)*/
	 , in_dtm                /* 에러 발생 시간 DATETIME */
  	 )
VALUES
	 ( #{mb_id}
	 , #{emp_cd}
	 , #{action_type}
	 , #{error_url}
	 , #{error_query_string}
	 , #{error_status}
	 , #{error_class}
	 , #{error_msg}
	 , #{error_trace}
	 , #{error_ip}
	 , NOW()
	 )

/* logs-mapper.xml id="insertActionLog" 액션 로그 입력 */
INSERT
  INTO tbsy_action_log
  	 ( mb_id                    /* 회사코드 VARCHAR(20)*/
	 , emp_cd                 /* 행위자 사번 VARCHAR(40)*/
	 , action_type            /* 행위 유형 VARCHAR(20)*/
	 , logging_ymd
	 , action_url             /* 호출 URL VARCHAR(200)*/
	 , action_query_string    /* URL에 전달된 파라미터 값 VARCHAR(1000)*/
	 , action_ip              /* 행위자 IP VARCHAR(100)*/
	 , in_dtm                 /* 입력 시간 DATETIME*/
  	 )
VALUES
	 ( #{mb_id}
	 , #{emp_cd}
	 , #{action_type}
	 , DATE_FORMAT(NOW(), '%Y-%m-%d')
	 , #{action_url}
	 , #{action_query_string}
	 , #{action_ip}
	 , NOW()
	 )

mapper.select:
/* logs-mapper.xml id="selectLoginHistList" 로그인 기록 조회 */
SELECT mb_id
     , emp_cd
     , DATE_FORMAT(MAX(login_dtm), '%Y-%m-%d %H:%i:%s') AS login_dtm
  FROM tbsy_login_hist
 WHERE mb_id = #{mb_id}
   AND emp_cd = #{emp_cd}
 GROUP BY mb_id, emp_cd
